#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "Pa/s".parse::<PressureChangeRateUnit>(),
        Ok(PressureChangeRateUnit::PascalPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "Pa/s").parse::<PressureChangeRate>(),
        Ok(PressureChangeRate::new(
            2.5,
            PressureChangeRateUnit::PascalPerSecond
        ))
    );
    assert_eq!(
        "kPa/s".parse::<PressureChangeRateUnit>(),
        Ok(PressureChangeRateUnit::KilopascalPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "kPa/s").parse::<PressureChangeRate>(),
        Ok(PressureChangeRate::new(
            2.5,
            PressureChangeRateUnit::KilopascalPerSecond
        ))
    );
    assert_eq!(
        "MPa/s".parse::<PressureChangeRateUnit>(),
        Ok(PressureChangeRateUnit::MegapascalPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "MPa/s").parse::<PressureChangeRate>(),
        Ok(PressureChangeRate::new(
            2.5,
            PressureChangeRateUnit::MegapascalPerSecond
        ))
    );
    assert_eq!(
        "Pa/min".parse::<PressureChangeRateUnit>(),
        Ok(PressureChangeRateUnit::PascalPerMinute)
    );
    assert_eq!(
        format!("2.5 {}", "Pa/min").parse::<PressureChangeRate>(),
        Ok(PressureChangeRate::new(
            2.5,
            PressureChangeRateUnit::PascalPerMinute
        ))
    );
    assert_eq!(
        "kPa/min".parse::<PressureChangeRateUnit>(),
        Ok(PressureChangeRateUnit::KilopascalPerMinute)
    );
    assert_eq!(
        format!("2.5 {}", "kPa/min").parse::<PressureChangeRate>(),
        Ok(PressureChangeRate::new(
            2.5,
            PressureChangeRateUnit::KilopascalPerMinute
        ))
    );
    assert_eq!(
        "MPa/min".parse::<PressureChangeRateUnit>(),
        Ok(PressureChangeRateUnit::MegapascalPerMinute)
    );
    assert_eq!(
        format!("2.5 {}", "MPa/min").parse::<PressureChangeRate>(),
        Ok(PressureChangeRate::new(
            2.5,
            PressureChangeRateUnit::MegapascalPerMinute
        ))
    );
    assert_eq!(
        "mmHg/s".parse::<PressureChangeRateUnit>(),
        Ok(PressureChangeRateUnit::MillimeterOfMercuryPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "mmHg/s").parse::<PressureChangeRate>(),
        Ok(PressureChangeRate::new(
            2.5,
            PressureChangeRateUnit::MillimeterOfMercuryPerSecond
        ))
    );
    assert_eq!(
        "atm/s".parse::<PressureChangeRateUnit>(),
        Ok(PressureChangeRateUnit::AtmospherePerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "atm/s").parse::<PressureChangeRate>(),
        Ok(PressureChangeRate::new(
            2.5,
            PressureChangeRateUnit::AtmospherePerSecond
        ))
    );
    assert_eq!(
        "psi/s".parse::<PressureChangeRateUnit>(),
        Ok(PressureChangeRateUnit::PoundForcePerSquareInchPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "psi/s").parse::<PressureChangeRate>(),
        Ok(PressureChangeRate::new(
            2.5,
            PressureChangeRateUnit::PoundForcePerSquareInchPerSecond
        ))
    );
    assert_eq!(
        "lb/in²/s".parse::<PressureChangeRateUnit>(),
        Ok(PressureChangeRateUnit::PoundForcePerSquareInchPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "lb/in²/s").parse::<PressureChangeRate>(),
        Ok(PressureChangeRate::new(
            2.5,
            PressureChangeRateUnit::PoundForcePerSquareInchPerSecond
        ))
    );
    assert_eq!(
        "kpsi/s".parse::<PressureChangeRateUnit>(),
        Ok(PressureChangeRateUnit::KilopoundForcePerSquareInchPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "kpsi/s").parse::<PressureChangeRate>(),
        Ok(PressureChangeRate::new(
            2.5,
            PressureChangeRateUnit::KilopoundForcePerSquareInchPerSecond
        ))
    );
    assert_eq!(
        "Mpsi/s".parse::<PressureChangeRateUnit>(),
        Ok(PressureChangeRateUnit::MegapoundForcePerSquareInchPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "Mpsi/s").parse::<PressureChangeRate>(),
        Ok(PressureChangeRate::new(
            2.5,
            PressureChangeRateUnit::MegapoundForcePerSquareInchPerSecond
        ))
    );
    assert_eq!(
        "psi/min".parse::<PressureChangeRateUnit>(),
        Ok(PressureChangeRateUnit::PoundForcePerSquareInchPerMinute)
    );
    assert_eq!(
        format!("2.5 {}", "psi/min").parse::<PressureChangeRate>(),
        Ok(PressureChangeRate::new(
            2.5,
            PressureChangeRateUnit::PoundForcePerSquareInchPerMinute
        ))
    );
    assert_eq!(
        "lb/in²/min".parse::<PressureChangeRateUnit>(),
        Ok(PressureChangeRateUnit::PoundForcePerSquareInchPerMinute)
    );
    assert_eq!(
        format!("2.5 {}", "lb/in²/min").parse::<PressureChangeRate>(),
        Ok(PressureChangeRate::new(
            2.5,
            PressureChangeRateUnit::PoundForcePerSquareInchPerMinute
        ))
    );
    assert_eq!(
        "kpsi/min".parse::<PressureChangeRateUnit>(),
        Ok(PressureChangeRateUnit::KilopoundForcePerSquareInchPerMinute)
    );
    assert_eq!(
        format!("2.5 {}", "kpsi/min").parse::<PressureChangeRate>(),
        Ok(PressureChangeRate::new(
            2.5,
            PressureChangeRateUnit::KilopoundForcePerSquareInchPerMinute
        ))
    );
    assert_eq!(
        "Mpsi/min".parse::<PressureChangeRateUnit>(),
        Ok(PressureChangeRateUnit::MegapoundForcePerSquareInchPerMinute)
    );
    assert_eq!(
        format!("2.5 {}", "Mpsi/min").parse::<PressureChangeRate>(),
        Ok(PressureChangeRate::new(
            2.5,
            PressureChangeRateUnit::MegapoundForcePerSquareInchPerMinute
        ))
    );
    assert_eq!(
        "bar/s".parse::<PressureChangeRateUnit>(),
        Ok(PressureChangeRateUnit::BarPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "bar/s").parse::<PressureChangeRate>(),
        Ok(PressureChangeRate::new(
            2.5,
            PressureChangeRateUnit::BarPerSecond
        ))
    );
    assert_eq!(
        "mbar/s".parse::<PressureChangeRateUnit>(),
        Ok(PressureChangeRateUnit::MillibarPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "mbar/s").parse::<PressureChangeRate>(),
        Ok(PressureChangeRate::new(
            2.5,
            PressureChangeRateUnit::MillibarPerSecond
        ))
    );
    assert_eq!(
        "bar/min".parse::<PressureChangeRateUnit>(),
        Ok(PressureChangeRateUnit::BarPerMinute)
    );
    assert_eq!(
        format!("2.5 {}", "bar/min").parse::<PressureChangeRate>(),
        Ok(PressureChangeRate::new(
            2.5,
            PressureChangeRateUnit::BarPerMinute
        ))
    );
    assert_eq!(
        "mbar/min".parse::<PressureChangeRateUnit>(),
        Ok(PressureChangeRateUnit::MillibarPerMinute)
    );
    assert_eq!(
        format!("2.5 {}", "mbar/min").parse::<PressureChangeRate>(),
        Ok(PressureChangeRate::new(
            2.5,
            PressureChangeRateUnit::MillibarPerMinute
        ))
    );
    assert_eq!(
        "1 not-a-unit".parse::<PressureChangeRate>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn arithmetic_f64() {
    let a = PressureChangeRate::from_base(6.0);
    let b = PressureChangeRate::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

#[test]
fn arithmetic_integer() {
    let a = PressureChangeRate::<i64>::from_base(7);
    let b = PressureChangeRate::<i64>::from_base(2);
    assert_eq!(a + b, PressureChangeRate::from_base(9));
    assert_eq!(a % b, PressureChangeRate::from_base(1));
    assert_eq!(a / b, 3);
    assert!(a > b);
    assert_eq!(
        [a, b].iter().sum::<PressureChangeRate<i64>>(),
        PressureChangeRate::from_base(9)
    );
}
